"""Regression coverage for the cinbase Services' table binding.

Every cinbase Service used to carry the ``cin`` attribute itself: each of the
nine duplicated Service bodies assigned ``self.cin = CinTable.cin`` after the
table load, so the attribute existed from the first moment the Service did.
When the nine bodies collapsed onto one shared module
(``python/cinbase/service.py``) that assignment was dropped, and the engine
(``python/cinbase/__init__.py``) reads ``cbTS.cin`` on every request
(``checkConfigChange``) while the loader writes it back only when a load
succeeds.

So while the table is still loading - or after a load that failed - the
attribute was simply absent, the engine's read raised ``AttributeError``, the
backend answered ``success: false`` and the keystroke was swallowed: no
composition, no candidates, no message. The user sees an IME that is active
and eats every key.

These cases drive the real service through the request dispatcher - the seam
the C++ client talks to - and assert on the reply it would see.
"""

import os
import sys
import threading
import time
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

import ime_smoke_runner  # noqa: E402 - located after ROOT is known
ime_smoke_runner.install_windows_shims()

from cinbase import LoadCinTable  # noqa: E402

LOADING_MESSAGE = '正在載入輸入法碼表，請稍候...'


class CinbaseTableBindingTests(unittest.TestCase):
    """The Service must carry its table binding before the table lands."""

    def setUp(self):
        self.old_appdata = os.environ.get("APPDATA")
        self.old_cwd = os.getcwd()
        import tempfile
        self.temp_dir = tempfile.TemporaryDirectory(prefix="pime-table-binding-")
        os.environ["APPDATA"] = self.temp_dir.name
        os.chdir(self.temp_dir.name)

        from input_methods.chesimplex import chesimplex_ime
        self.module = chesimplex_ime
        # The holder is a class-level singleton shared by every service in the
        # process; start from a pristine one so the constructor spawns a load
        # of its own instead of joining a finished one.
        self.module.CinTable.reset()
        self._release = threading.Event()
        self._original_load = LoadCinTable._load_table

    def tearDown(self):
        LoadCinTable._load_table = self._original_load
        self._release.set()
        os.chdir(self.old_cwd)
        if self.old_appdata is None:
            os.environ.pop("APPDATA", None)
        else:
            os.environ["APPDATA"] = self.old_appdata
        self.temp_dir.cleanup()

    def _block_the_table_load(self):
        """Hold the table load open so the Service has no table yet."""
        original = self._original_load
        release = self._release

        def slow_load(loader, *args, **kwargs):
            release.wait(30)
            return original(loader, *args, **kwargs)

        LoadCinTable._load_table = slow_load

    def _new_service(self):
        service = self.module.CheSimplexTextService(ime_smoke_runner.FakeClient())
        reply = service.handleRequest(
            {"method": "onActivate", "isKeyboardOpen": True, "seqNum": 1})
        self.assertTrue(reply.get("success"), "onActivate failed: %r" % reply)
        return service

    def test_a_key_while_the_table_loads_gets_an_answer(self):
        """The request path must answer, not die on a missing binding.

        This is the shape of the report: the IME is active, the key never
        reaches the editor, and the backend log shows an AttributeError for
        ``cbTS.cin`` on every keystroke.
        """
        self._block_the_table_load()
        service = self._new_service()

        for method in ("filterKeyDown", "onKeyDown"):
            reply = service.handleRequest(
                ime_smoke_runner.key_event(method, ord('a')))
            self.assertIsInstance(reply, dict,
                                  "the keystroke died instead of being answered")
            self.assertTrue(reply.get("success"),
                            "%s died instead of being answered: %r" % (method, reply))
            # The key is held by the IME while the table is still loading, so
            # the editor never sees the raw Latin letter.
            self.assertTrue(reply.get("return"),
                            "%s let the raw key through to the editor: %r" % (method, reply))

    def test_the_service_carries_its_table_binding_from_the_start(self):
        """The binding exists before the table lands, and holds the table
        once it does."""
        self._block_the_table_load()
        service = self._new_service()

        self.assertTrue(hasattr(service, "cin"),
                        "the Service must carry a table binding before the table lands")
        self.assertIsNone(service.cin)

        # Let the load finish: the binding must pick the table up.
        self._release.set()
        for _ in range(500):
            if self.module.CinTable.cin is not None and not self.module.CinTable.loading:
                break
            time.sleep(0.02)
        self.assertIsNotNone(self.module.CinTable.cin,
                             "the table must still load after the fix")
        self.assertIsNotNone(service.cin,
                             "the Service must adopt the loaded table")


if __name__ == "__main__":
    unittest.main()
